def shortest_at_least(nums, target):
    n = len(nums)
    prefix = [0] * (n + 1)
    for i, x in enumerate(nums):
        prefix[i + 1] = prefix[i] + x

    ans = n + 1
    dq = [0]
    head = 0

    for i in range(n + 1):
        while head < len(dq) and prefix[i] - prefix[dq[head]] >= target:
            length = i - dq[head]
            if length < ans:
                ans = length
            head += 1

        while head < len(dq) and prefix[dq[-1]] >= prefix[i]:
            dq.pop()

        dq.append(i)

    return ans if ans <= n else -1

def order_nodes(n, edges):
    if n == 0:
        return []

    indegree = [0] * n
    adjacency = [[] for _ in range(n)]

    for edge in edges:
        a = edge[0]
        b = edge[1]
        adjacency[a].append(b)
        indegree[b] += 1

    heap = []

    def heap_push(value):
        heap.append(value)
        i = len(heap) - 1
        while i > 0:
            parent = (i - 1) // 2
            if heap[parent] <= heap[i]:
                break
            heap[parent], heap[i] = heap[i], heap[parent]
            i = parent

    def heap_pop():
        root = heap[0]
        last = heap.pop()
        if heap:
            heap[0] = last
            i = 0
            length = len(heap)
            while True:
                left = 2 * i + 1
                right = left + 1
                smallest = i
                if left < length and heap[left] < heap[smallest]:
                    smallest = left
                if right < length and heap[right] < heap[smallest]:
                    smallest = right
                if smallest == i:
                    break
                heap[i], heap[smallest] = heap[smallest], heap[i]
                i = smallest
        return root

    for node in range(n):
        if indegree[node] == 0:
            heap_push(node)

    result = []

    while heap:
        node = heap_pop()
        result.append(node)
        for neighbor in adjacency[node]:
            indegree[neighbor] -= 1
            if indegree[neighbor] == 0:
                heap_push(neighbor)

    if len(result) != n:
        return None
    return result
